"""Line coverage of the RTL measured by Verilator (--coverage-line) over the top tests, merged with verilator_coverage.

Each top test is built again with line coverage into sim/cov_<name>, run with its vectors, and its coverage.dat is merged into
sim/cov_merged.dat; verilator_coverage --annotate writes the annotated sources to sim/cov_annotate and the per-file summary
is written to docs/COVERAGE_LINE.md (lines hit / lines instrumented per RTL file). Line coverage only: no toggle, branch or
functional coverage.
Usage: python run_coverage.py [--merge-only | --runs=a,b]   (--merge-only: reuse the coverage.dat files of an earlier run;
--runs: build and run only these runs, then merge them with the coverage.dat files of the others)"""
import os
import re
import subprocess
import sys

V = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..')).replace(chr(92), '/')
S = V + '/sim'
PY = sys.executable
VCOV = 'C:/Tools/oss-cad-suite/bin/verilator_coverage_bin.exe'
RUNS = [
    ('top_ec_quick', ['top_ec', '+VEC=' + S + '/quick.hex', '+NVEC=10'], ''),
    ('top_ec_edvar', ['top_ec', '+VEC=' + S + '/top_edvar.hex', '+NVEC=68'], ''),
    ('top_ec_det', ['top_ec', '+VEC=' + S + '/det.hex', '+NVEC=26'], '-DTB_RNG_SRC=1 -DTB_DPA_EC=1'),
    ('top_pq_lat', ['top_pq', '+DIR=' + S + '/lat_all', '+KIND=lat', '+NVEC=25'], '-DTB_DPA_PQ=1'),
    ('top_pq_latpre', ['top_pq', '+DIR=' + S + '/lat_prehash', '+KIND=lat', '+NVEC=16'], ''),
    ('top_pq_hbs', ['top_pq', '+DIR=' + S + '/hbs_quick', '+KIND=hbs', '+NVEC=19'], ''),
    ('top_pq_hbspre', ['top_pq', '+DIR=' + S + '/hbs_prehash', '+KIND=hbs', '+NVEC=12'], ''),
    ('top_err', ['top_err'], ''),
    ('top_sys', ['top_sys', '+DIR=' + S + '/sys'], ''),
    # unit tests of the blocks whose error and corner paths the top tests do not reach
    ('axi', ['axi'], ''),
    ('key_rng', ['key_rng'], ''),
    ('rng_drbg', ['rng_drbg', '+VEC=' + S + '/drbg_vec.txt'], ''),
    ('rng_katfail', ['rng_drbg', '+VEC=' + S + '/drbg_vec.txt', '+KATFAIL'], ''),
    ('hseq', ['hseq', '+VEC=' + S + '/hseq_final.txt'], ''),
    ('hfeed', ['hfeed', '+VEC=' + S + '/hfeed_final.txt'], ''),
]


def main():
    dats = []
    merge_only = '--merge-only' in sys.argv
    only = [a.split('=', 1)[1].split(',') for a in sys.argv if a.startswith('--runs=')]
    todo = [r for r in RUNS if not only or r[0] in only[0]]
    for i in range(0, 0 if merge_only else len(todo), 3):          # three builds at a time (memory)
        procs = []
        for name, args, defs in todo[i:i + 3]:
            env = dict(os.environ)
            env['UNIT_TAG'] = '_cov_' + name
            env['UNIT_DEFS'] = (defs + ' --coverage-line').strip()
            procs.append((name, args[0], subprocess.Popen([PY, 'env/misc/run_unit.py'] + args, cwd=V, env=env,
                                                          stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)))
        for name, unit, p in procs:
            p.wait()
            d = '%s/%s_cov_%s/coverage.dat' % (S, unit, name)
            print('%-14s %s' % (name, 'coverage.dat' if os.path.exists(d) else 'NO coverage.dat'), flush=True)
            if os.path.exists(d):
                dats.append(d)
    if merge_only or only:
        dats = []
        for name, args, _ in RUNS:
            d = '%s/%s_cov_%s/coverage.dat' % (S, args[0], name)
            print('%-14s %s' % (name, 'coverage.dat' if os.path.exists(d) else 'NO coverage.dat'), flush=True)
            if os.path.exists(d):
                dats.append(d)
    subprocess.run([VCOV, '--write', S + '/cov_merged.dat'] + dats, check=True)
    r = subprocess.run([VCOV, '--annotate', S + '/cov_annotate', '--annotate-min', '1', S + '/cov_merged.dat'],
                       capture_output=True, text=True)
    print(r.stdout[-400:])
    rows = []
    for f in sorted(os.listdir(S + '/cov_annotate')):
        if not f.startswith('m_vlsit_dsig') and not f.startswith('m_vlsit_sha') and not f.startswith('m_vlsit_csr'):
            continue
        txt = open(S + '/cov_annotate/' + f, errors='replace').read().splitlines()
        # an instrumented line starts with its counter: ' <count>' (6 or more digits) when hit, '%000000' when never hit
        hit = sum(1 for l in txt if re.match(r'^ +[0-9]{6,} ', l) and not re.match(r'^ +0+ ', l))
        miss = sum(1 for l in txt if l.startswith('%0'))
        tot = hit + miss
        rows.append((f, hit, tot))
    lines = ['# Line coverage of the RTL (Verilator --coverage-line)', '',
             'Generated by `verification/env/misc/run_coverage.py`: the top tests (EC quick, Ed variants, RFC 6979 with Hash_DRBG and '
             'blinding, ML-DSA with masking, HashML-DSA, hash-based, HashSLH-DSA, errors, system) and the unit tests of the AXI4, '
             'key, random, Hash_DRBG, hash sequencer and feeder blocks, merged. A line counts as hit when its counter is at least 1. '
             'Not in these numbers: the engine tests alone (tb_ec, tb_lat, tb_hbs, slow with coverage) and phase 1 (Icarus, no '
             'coverage).',
             '', '| File | Lines hit | Lines instrumented | Coverage |', '|---|---|---|---|']
    for f, hit, tot in rows:
        note = ' (ROM: not in the total)' if f.endswith('_rom.sv') else ''
        lines.append('| %s%s | %d | %d | %.1f %% |' % (f, note, hit, tot, 100.0 * hit / tot if tot else 0))
    # the generated program ROMs are one large case statement: Verilator instruments only part of the arms (and turns the rest
    # into a table), so their line numbers do not measure which instructions ran; they are listed but left out of the total
    th = sum(r[1] for r in rows if not r[0].endswith('_rom.sv'))
    tt = sum(r[2] for r in rows if not r[0].endswith('_rom.sv'))
    # result line of each instrumented run (a run without run.log exceeded the 3000 s limit of run_unit.py: its pass line was
    # not recorded although the simulation finished and wrote coverage.dat; its pass comes only from the regression logs)
    lines += ['', '| Run | Result of the instrumented run |', '|---|---|']
    for name, args, _ in RUNS:
        lg = '%s/%s_cov_%s/run.log' % (S, args[0], name)
        res = [l.strip() for l in open(lg, errors='replace') if l.startswith('RESULT')] if os.path.exists(lg) else []
        lines.append('| %s | %s |' % (name, res[-1] if res else 'no run.log: exceeded the 3000 s limit of run_unit.py, '
                                       'coverage.dat written at the end of the simulation; pass line only in the regression run'))
    lines += ['', 'Total without the program ROMs: %d of %d lines (%.1f %%). The ROM files (`*_rom.sv`) are one large case '
              'statement; Verilator instruments only part of its arms, so their numbers do not say which instructions ran. The '
              'programs are covered by the engine tests and the bit-exact Python models (ENGINES.md). Lines never hit: see '
              'the lines starting with %%000000 in sim/cov_annotate.' % (th, tt, 100.0 * th / tt if tt else 0)]
    open(V + '/docs/COVERAGE_LINE.md', 'w', encoding='utf-8').write('\n'.join(lines) + '\n')
    print('docs/COVERAGE_LINE.md written: %d files, %d of %d lines' % (len(rows), th, tt))


if __name__ == '__main__':
    main()
